+        _isAuthenticated = user.Identity?.IsAuthenticated == true;
+        if (_isAuthenticated)
+        {
+            _userName = user.Identity!.Name;
+            _roles = user.FindAll(System.Security.Claims.ClaimTypes.Role)
+                         .Select(c => c.Value)
+                         .ToList();
+        }
+    }
+}
